            "gem error",
            "retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("bundler"), "Should show step name");
        assert!(ui.has_message("bundle install"), "Should show command");
        assert!(ui.has_message("gem error"), "Should show error");
        assert!(ui.has_message("retry"), "Should show recovery action");
    }

